for turn in range(MAX_TURNS):
    resp = client.messages.create(model=MODEL, max_tokens=8000, tools=TOOLS, messages=msgs)
    msgs.append({"role": "assistant", "content": resp.content})  # full content
    if resp.stop_reason == "max_tokens":
        raise Truncated()            # never run tools from this turn
    if resp.stop_reason != "tool_use":
        break                        # end_turn / refusal handled by caller
    results = [run(b) for b in resp.content if b.type == "tool_use"]
    msgs.append({"role": "user", "content": results})  # one message, all results
else:
    raise TurnLimit()

