def issue_refund(order_id: str, ctx: Session):
    if not ctx.identity_verified_for(ctx.customer_id):
        return tool_error("Identity not verified. Call verify_identity first.",
                          retryable=False)
    order = orders.get(order_id)               # amount comes from the system
    if order.customer_id != ctx.customer_id:
        return tool_error("Order does not belong to this customer.")
    if order.amount > 500:
        return queue_for_approval(order)       # human gate in code
    return refunds.create(order)

async def trim_doc(input_data, tool_use_id, ctx):
    out = input_data["tool_response"]
    return {"hookSpecificOutput": {
        "hookEventName": "PostToolUse",
        "updatedToolOutput": normalize(out)}}   # ISO dates, drop raw metadata

